import json, re, math
from pathlib import Path

with open('/root/report_template.json') as f:
    template=json.load(f)
with open('/root/diagpanel_policy_report.json') as f:
    report=json.load(f)
summary=Path('/root/diagpanel_policy_summary.md').read_text()

errors=[]
if report.get('metadata') != template.get('metadata'):
    errors.append('metadata mismatch')
if report.get('audit_notes') != template.get('audit_notes'):
    errors.append('audit_notes mismatch')
req_assumptions={
 'runs_per_year_14_day':26,
 'runs_per_year_28_day':13,
 'switch_threshold_usd':6000,
 'override_rule':'highest numeric approved rev with non-empty active_labs, else default_active_labs',
 'holdout_rule':'exclude holdout_state=exclude',
 'adjustment_rule':'missing network_tier adjustment defaults to 0.0'
}
ass=report['analysis'].get('assumptions',{})
if ass != req_assumptions:
    errors.append(f'assumptions mismatch: {ass!r}')
required_panel_fields={
 'panel_code','panel_name','active_labs','reagent_cost_per_1000_tests_usd','network_tier',
 'network_adjustment_per_run_per_lab_usd','shipper_class','shipper_cost_usd',
 'base_payment_per_run_per_lab_usd','total_payment_per_run_per_lab_usd',
 'tests_per_lab_per_run_14_day','tests_per_lab_per_run_28_day',
 'annual_reagent_cost_14_day_usd','annual_reagent_cost_28_day_usd',
 'annual_shipper_cost_14_day_usd','annual_shipper_cost_28_day_usd',
 'annual_revenue_14_day_usd','annual_revenue_28_day_usd',
 'annual_margin_14_day_usd','annual_margin_28_day_usd',
 'annual_margin_difference_28_minus_14_usd'
}
panels=report['analysis'].get('panels',[])
for p in panels:
    missing=required_panel_fields-set(p)
    extra=set(p)-required_panel_fields
    if missing:
        errors.append(f'{p.get("panel_code")} missing {sorted(missing)}')
# all required fields from schema means at least no missing; extra not error.
codes=[p['panel_code'] for p in panels]
if codes != sorted(codes):
    errors.append(f'panels not sorted: {codes}')
# check currency numeric values have <=2 decimal places by integer cents comparison
currency_suffixes=('_usd',)
for section in [report['analysis'].get('totals',{})] + panels:
    for k,v in section.items():
        if k.endswith(currency_suffixes) and isinstance(v,(int,float)):
            if abs(v*100-round(v*100)) > 1e-9:
                errors.append(f'{k} not rounded to cents: {v}')
lines=[line for line in summary.splitlines() if line.strip()]
if not (4 <= len(lines) <= 8):
    errors.append(f'summary non-empty line count {len(lines)}')
decision=report['analysis']['recommendation']['decision']
if decision not in summary:
    errors.append('summary missing exact decision slug')
for key in ['total_annual_margin_14_day_usd','total_annual_margin_28_day_usd','absolute_total_margin_difference_usd']:
    val=report['analysis']['totals'][key]
    if f'{val:,.2f}' not in summary:
        errors.append(f'summary missing formatted {key}')
if '$' in summary:
    errors.append('summary contains $ prefix/symbol')
# verify known data choices from inputs
expected_codes=['DP-ALPHA','DP-BETA','DP-DELTA','DP-EPS','DP-GAMMA']
if codes != expected_codes:
    errors.append(f'unexpected retained codes {codes}')
expected_labs={'DP-ALPHA':17,'DP-BETA':13,'DP-DELTA':10,'DP-EPS':11,'DP-GAMMA':9}
for p in panels:
    if p['active_labs'] != expected_labs[p['panel_code']]:
        errors.append(f'active_labs mismatch for {p["panel_code"]}: {p["active_labs"]}')
if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-',e)
    raise SystemExit(1)
print('VALIDATION PASSED')
print('metadata and audit_notes match template exactly')
print('assumptions keys/values correct')
print('panel fields complete; panel_code order:', codes)
print('currency values rounded to 2 decimals')
print('summary non-empty lines:', len(lines))
print('summary includes totals and exact decision slug without $')
